update public.problems set hidden_tests = '[{"label":"Symmetric deeper","inputJson":"{\"root\":[1,2,2,3,4,4,3,5,6,7,8,8,7,6,5]}","expectedJson":"true"},{"label":"Values symmetric structure not","inputJson":"{\"root\":[1,2,2,3,null,null,3]}","expectedJson":"true"},{"label":"Structure symmetric values not","inputJson":"{\"root\":[1,2,2,3,4,4,5]}","expectedJson":"false"},{"label":"Right-only child","inputJson":"{\"root\":[1,null,2]}","expectedJson":"false"},{"label":"Left-only child","inputJson":"{\"root\":[1,2]}","expectedJson":"false"},{"label":"Negative values symmetric","inputJson":"{\"root\":[-1,-2,-2,-3,-4,-4,-3]}","expectedJson":"true"}]'::jsonb where slug = 'symmetric-tree';
