update public.problems set hidden_tests = '[{"label":"Two singletons only","inputJson":"{\"nums\":[7,13]}","expectedJson":"[7, 13]"},{"label":"Includes zero singleton","inputJson":"{\"nums\":[5,5,3,3,0,9]}","expectedJson":"[9, 0]"},{"label":"Both negative","inputJson":"{\"nums\":[-2,-2,-3,-5,1,1]}","expectedJson":"[-5, -3]"},{"label":"Max int boundary","inputJson":"{\"nums\":[2147483647,-2147483648,1,1,2,2]}","expectedJson":"[2147483647, -2147483648]"},{"label":"Singletons differ by one bit","inputJson":"{\"nums\":[1,2,1,2,8,9]}","expectedJson":"[9, 8]"},{"label":"Many duplicates plus two","inputJson":"{\"nums\":[10,20,30,10,20,30,100,200]}","expectedJson":"[100, 200]"}]'::jsonb where slug = 'single-number-iii';
update public.problems set hidden_tests = '[{"label":"Max flips needed (both set, target zero)","inputJson":"{\"a\":7,\"b\":7,\"c\":8}","expectedJson":"7"},{"label":"Large values","inputJson":"{\"a\":1000000000,\"b\":1,\"c\":999999999}","expectedJson":"9"},{"label":"All same","inputJson":"{\"a\":5,\"b\":5,\"c\":5}","expectedJson":"0"},{"label":"a equals c, b is subset","inputJson":"{\"a\":31,\"b\":15,\"c\":31}","expectedJson":"0"},{"label":"Target has extra high bit","inputJson":"{\"a\":1,\"b\":2,\"c\":7}","expectedJson":"1"},{"label":"Both inputs equal target disjoint bits","inputJson":"{\"a\":8,\"b\":8,\"c\":1}","expectedJson":"3"}]'::jsonb where slug = 'minimum-flips-to-make-a-or-b-equal-to-c';
update public.problems set hidden_tests = '[{"label":"Both negative","inputJson":"{\"a\":-500,\"b\":-500}","expectedJson":"-1000"},{"label":"Negative larger magnitude","inputJson":"{\"a\":-1000,\"b\":5}","expectedJson":"-995"},{"label":"At boundary lower","inputJson":"{\"a\":-1000,\"b\":-1}","expectedJson":"-1001"},{"label":"At boundary upper","inputJson":"{\"a\":1000,\"b\":1000}","expectedJson":"2000"},{"label":"Mixed sign cancel","inputJson":"{\"a\":-7,\"b\":7}","expectedJson":"0"},{"label":"One zero one negative","inputJson":"{\"a\":0,\"b\":-1000}","expectedJson":"-1000"}]'::jsonb where slug = 'sum-of-two-integers';
update public.problems set hidden_tests = '[{"label":"Zero is singleton","inputJson":"{\"nums\":[7,7,7,0]}","expectedJson":"0"},{"label":"Negative singleton","inputJson":"{\"nums\":[3,3,3,-4]}","expectedJson":"-4"},{"label":"All triples negative plus one","inputJson":"{\"nums\":[-2,-2,-2,-1,-1,-1,5]}","expectedJson":"5"},{"label":"Max int singleton","inputJson":"{\"nums\":[1,1,1,2147483647]}","expectedJson":"2147483647"},{"label":"Most negative singleton","inputJson":"{\"nums\":[1,1,1,-2147483648]}","expectedJson":"-2147483648"},{"label":"Singleton among larger list","inputJson":"{\"nums\":[10,20,30,10,20,30,10,20,30,42]}","expectedJson":"42"}]'::jsonb where slug = 'single-number-ii';
